import resonance.si as si
import resonance.db as db
from resonance.internal import declare_transformation, Processor
import numpy as np
import h5py

@declare_transformation
class signal_creator(Processor):
    def __init__(self):
        self._matrix = None
        self._si = None

    def prepare(self, channels: db.Channels, filename):
        """
        :param channels: db.Channels
        :param matrix: np.ndarray
        :return:
        """
        
        if not isinstance(channels, db.Channels):
            raise Exception("Input must be Channels")
        # if len(matrix.shape) != 2:
        #     raise Exception("Matrix should be 2 dimensional")
        # if channels.SI.channels != np.size(matrix, 0):
        #     raise Exception("Number of rows in matrix should match number of channels")

        # self._matrix = len(channels)
      
        self._si = si.Channels(
            channels=65, samplingRate=channels.SI.samplingRate
        )
       
        with h5py.File(filename, 'r') as h5f:
            self.eeg = h5f['eeg/data'][:]
            packs = h5f['eeg/blocks'][:]
        self.packs =  np.array([pack[-1] for pack in packs]) #np.full(len(packs), fill_value=100)
        self.ind_pack = 0
        self.ind_sample = 0
        return self._si

    def online(self, channels):
        pack = self.packs[self.ind_pack]
        ret = self.eeg[self.ind_sample:self.ind_sample+pack]
        self.ind_sample += pack
        self.ind_pack += 1
        # ret = np.matmul(channels, self._matrix)
        return db.Channels(self._si, channels.TS, ret)
